// bundle.js — the per-app bundle zip from the powerapps-canvas-yaml skill, built from the project:
//   canonical/<screen>.pa.yaml + canonical/App.pa.yaml   what gets pasted (source of truth)
//   schema/schema.json                                    every list: column, display name, type
//   flows/<flow>/definition.json                          flow definitions (as in an export)
//   reports/lint.txt, reports/drift.txt                   lint and the last Studio-export check
//   CHANGELOG.md, bundle.json                             history; bundle.json embeds the project
// export/ and export_src/ hold a Studio export and are only kept when a bundle that had them is
// re-exported from a project that came from it; tools/ is not shipped by the studio.
import { normalizeProject, newList, newColumn, COLTYPES } from './core.js';
import { screenYaml, themeFormulas, onStartFx, startScreenFx, lint } from './emit.js';
import { flowPackageFiles, internalName } from './flows.js';
import { importYaml } from './import.js';

export const FORMAT = 'power-app-studio-bundle';
const SP_TYPE = { Text: 'Text', Note: 'Note', Number: 'Number', Currency: 'Currency', DateTime: 'DateTime', Choice: 'Choice', YesNo: 'Boolean', Person: 'User', Lookup: 'Lookup' };
const FROM_SP = { ...Object.fromEntries(Object.entries(SP_TYPE).map(([k, v]) => [v, k])), MultiChoice: 'Choice', UserMulti: 'Person', LookupMulti: 'Lookup' };
const slugName = (n) => String(n || 'App').replace(/[^A-Za-z0-9]+/g, '') || 'App';

/** schema.json digest: {lists:[{name, columns:[{name, display, type, required, choices?, lookupList?}]}]} */
export function schemaDigest(project) {
  return {
    generated: new Date().toISOString().slice(0, 10),
    lists: project.lists.map((l) => ({
      name: l.name,
      columns: l.columns.map((c) => ({
        name: c.builtin ? 'Title' : internalName(c.name), display: c.name, type: SP_TYPE[c.type] || 'Text', required: !!c.required,
        ...(c.type === 'Choice' ? { choices: [...c.choices] } : {}), ...(c.type === 'Lookup' ? { lookupList: c.lookupList } : {}),
      })),
    })),
  };
}
/** Lists from a schema digest (also accepts the studio's own {lists:[{name, columns:[{name, type}]}]}). */
export function listsFromDigest(d) {
  return (d?.lists || []).map((l) => {
    const list = newList(String(l.name || 'List'));
    for (const c of l.columns || []) {
      const nm = String(c.display || c.name || '').replace(/\s+/g, '');
      if (!nm || /^(Title|ID|Created|Modified|Author|Editor)$/.test(nm)) { if (nm === 'Title' && c.required === false) list.columns[0].required = false; continue; }
      const type = COLTYPES[c.type] ? c.type : FROM_SP[c.type] || 'Text';
      list.columns.push(newColumn(nm, type, { required: !!c.required, choices: type === 'Choice' ? (c.choices || []).map(String) : [], lookupList: type === 'Lookup' ? String(c.lookupList || '') : '' }));
    }
    return list;
  });
}
const block = (pad, key, fx) => `${pad}${key}: |-\n` + ('=' + fx).split('\n').map((l) => (l ? pad + '  ' + l : '')).join('\n');
export function appYaml(project) {
  const lines = ['App:', '  Properties:', block('    ', 'Formulas', themeFormulas(project))];
  const os = onStartFx(project);
  if (os) lines.push(block('    ', 'OnStart', os));
  lines.push(block('    ', 'StartScreen', startScreenFx(project)));
  return lines.join('\n') + '\n';
}
function changelog(project) {
  const out = [`# ${project.app.name} — changelog`, '', '_Generated by Power App Studio from the project history._', ''];
  const snaps = [...(project.snapshots || [])].reverse();
  if (snaps.length) { out.push('## Snapshots'); for (const s of snaps) out.push(`- ${s.at.slice(0, 16).replace('T', ' ')} — ${s.name}${s.auto ? ' (automatic)' : ''}`); out.push(''); }
  const dep = Object.entries(project.deployed || {}).sort((a, b) => String(b[1].at).localeCompare(String(a[1].at)));
  if (dep.length) { out.push('## Deployed (Paste assistant)'); for (const [, v] of dep) out.push(`- ${String(v.at).slice(0, 16).replace('T', ' ')} — ${v.name || 'step'}`); out.push(''); }
  if (!snaps.length && !dep.length) out.push('No history yet.', '');
  return out.join('\n');
}

/** Bundle files: {path: text}. */
export function bundleFiles(project, { date = new Date().toISOString().slice(0, 10) } = {}) {
  const app = slugName(project.app.name);
  const root = `${app}_bundle_${date}`;
  const files = {};
  project.screens.forEach((s) => { files[`${root}/canonical/${s.name}.pa.yaml`] = screenYaml(project, s); });
  files[`${root}/canonical/App.pa.yaml`] = appYaml(project);
  files[`${root}/schema/schema.json`] = JSON.stringify(schemaDigest(project), null, 2);
  for (const f of (project.flows || []).filter((x) => x.enabled !== false)) {
    const pkg = flowPackageFiles(project, f);
    const def = Object.entries(pkg).find(([k]) => k.endsWith('/definition.json'));
    if (def) files[`${root}/flows/${slugName(f.name)}/definition.json`] = JSON.stringify(JSON.parse(def[1]), null, 2);
  }
  files[`${root}/reports/lint.txt`] = lint(project).map((x) => `${x.level.toUpperCase()}\t${x.code}\t${x.where}\t${x.msg}`).join('\n') || 'No findings.';
  files[`${root}/reports/drift.txt`] = 'Not checked here. In Power App Studio use Project → Check against a Studio export, or run screen_tool.py bundle refresh with a newer Studio export.';
  files[`${root}/CHANGELOG.md`] = changelog(project);
  files[`${root}/bundle.json`] = JSON.stringify({ format: FORMAT, version: 1, app: project.app.name, created: new Date().toISOString(), generator: 'Power App Studio', files: Object.keys(files).map((k) => k.slice(root.length + 1)), project }, null, 2);
  return { name: `${root}.zip`, root, files };
}
export async function bundleZip(project, JSZip) {
  const { name, files } = bundleFiles(project);
  const z = new JSZip();
  for (const [p, t] of Object.entries(files)) z.file(p, t);
  return { name, blob: await z.generateAsync({ type: typeof Blob !== 'undefined' ? 'blob' : 'uint8array' }) };
}

/** Read a bundle zip. Returns {project, source: 'embedded'|'canonical', notes}. */
export async function readBundle(data, JSZip, makeProject) {
  const z = await JSZip.loadAsync(data);
  const entries = Object.entries(z.files).filter(([, e]) => !e.dir);
  const find = (re) => entries.find(([p]) => re.test(p));
  const notes = [];
  const bj = find(/(^|\/)bundle\.json$/);
  if (bj) {
    let meta = null;
    try { meta = JSON.parse(await bj[1].async('string')); } catch { notes.push('bundle.json is not valid JSON; reading the canonical screens instead.'); }
    if (meta?.project && typeof meta.project === 'object') return { project: normalizeProject(meta.project), source: 'embedded', notes };
    if (meta && !meta.project) notes.push('This bundle has no embedded Power App Studio project (made by screen_tool.py); rebuilt it from canonical/ and schema/.');
  }
  const p = makeProject();
  p.screens = [];
  const sj = find(/(^|\/)schema\/schema\.json$/);
  if (sj) { try { p.lists = listsFromDigest(JSON.parse(await sj[1].async('string'))); } catch { notes.push('schema/schema.json could not be read; lists left empty.'); } }
  else notes.push('No schema/schema.json in the bundle; lists left empty.');
  const screens = entries.filter(([pth]) => /(^|\/)canonical\/[^/]+\.pa\.yaml$/.test(pth) && !/App\.pa\.yaml$/.test(pth)).sort((a, b) => a[0].localeCompare(b[0]));
  if (!screens.length) throw new Error('No canonical/*.pa.yaml screens and no embedded project: this does not look like an app bundle.');
  for (const [pth, e] of screens) {
    try { const r = importYaml(p, await e.async('string')); p.screens.push(...r.screens); }
    catch (err) { notes.push(`${pth.split('/').pop()}: ${err.message}`); }
  }
  const ap = find(/(^|\/)canonical\/App\.pa\.yaml$/);
  if (ap) {
    const txt = await ap[1].async('string');
    // StartScreen is a bare screen name or If(IsBlank(Param("ID")), start, deepLinkScreen): the first screen named wins.
    const m = txt.match(/StartScreen:\s*(?:\|-?\s*\n)?\s*=?([^\n]+)/);
    const names = m ? m[1].match(/[A-Za-z_]\w*/g) || [] : [];
    const s = names.map((n) => p.screens.find((x) => x.name === n)).find(Boolean);
    if (s) p.app.startScreen = s.id;
    notes.push('App.Formulas and OnStart were not imported: the theme starts from the default, and generated OnStart is rebuilt from the screens.');
  }
  const appName = (screens[0][0].split('/')[0].match(/^(.+?)_bundle_/) || [])[1];
  if (appName) p.app.name = appName;
  if (!p.screens.length) throw new Error('None of the screens in the bundle could be read.');
  if (!p.screens.some((x) => x.id === p.app.startScreen)) p.app.startScreen = p.screens[0].id;
  return { project: normalizeProject(p), source: 'canonical', notes };
}
